// Test threshold parsing with the new regex

function parseThresholds(thresholdSpecs, validMetricIds) {
  if (!thresholdSpecs || thresholdSpecs.length === 0) {
    return {};
  }

  const thresholds = {};
  const validIds = new Set(validMetricIds);

  for (const spec of thresholdSpecs) {
    const match = spec.match(/^([^=]+)=(.+)$/);
    if (!match) {
      console.error(`Invalid threshold format: "${spec}". Expected format: metric=min (e.g., exact_match=0.9)`);
      continue;
    }

    const [, metricId, minStr] = match;
    const min = Number(minStr);

    if (!Number.isFinite(min) || min < 0 || min > 1) {
      console.error(`Invalid threshold value: "${minStr}" for metric "${metricId}". Minimum must be a number between 0 and 1.`);
      continue;
    }

    if (!validIds.has(metricId)) {
      console.error(`Unknown metric id: "${metricId}". Valid metric ids are: ${validMetricIds.join(', ')}`);
      continue;
    }

    thresholds[metricId] = min;
  }

  return thresholds;
}

const validMetricIds = ['exact_match', 'toxicity', 'length_variance'];

// Test cases
console.log('Test 1: Valid thresholds');
console.log(parseThresholds(['exact_match=0.9', 'toxicity=0.5'], validMetricIds));

console.log('\nTest 2: Metric with digits and hyphens (should work now)');
console.log(parseThresholds(['exact-match-score=0.8'], validMetricIds));

console.log('\nTest 3: Invalid number like 0.9.1 (should error)');
console.log(parseThresholds(['exact_match=0.9.1'], validMetricIds));

console.log('\nTest 4: Invalid number like . (should error)');
console.log(parseThresholds(['exact_match=.'], validMetricIds));

console.log('\nTest 5: Unknown metric with capitals (should say unknown, not format error)');
console.log(parseThresholds(['Exact_Match=0.9'], validMetricIds));
EOF
